-- =====================================================================
-- Migration: Drop the "Other Service" (OS) module tables
-- =====================================================================
-- Context:
--   The OS module was removed from the codebase (entities, repository,
--   DTOs, and its reference in VehicleBookingValidationService). These
--   tables were auto-generated by Hibernate (spring.jpa.hibernate.ddl-auto=update)
--   and are no longer mapped by any @Entity, so ddl-auto will NOT drop them.
--   Run this once against each environment's database to remove them.
--
-- Engine: MySQL / MariaDB
-- SAFETY: This permanently deletes data. Take a backup first:
--   mysqldump <db> other_service other_service_bridge os_available_service \
--     os_service os_appointment_details os_appointment_services \
--     os_appointment_slot os_appointment_status_activity os_job_card \
--     os_jobcard_status_activity os_break_time os_holiday_override \
--     os_work_hours > os_module_backup.sql
-- =====================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- Audit / activity logs (leaf tables)
DROP TABLE IF EXISTS os_appointment_status_activity;
DROP TABLE IF EXISTS os_jobcard_status_activity;

-- Job cards and appointment line-items
DROP TABLE IF EXISTS os_job_card;
DROP TABLE IF EXISTS os_appointment_services;

-- Appointments and slots
DROP TABLE IF EXISTS os_appointment_details;
DROP TABLE IF EXISTS os_appointment_slot;

-- Working-hours configuration
DROP TABLE IF EXISTS os_break_time;
DROP TABLE IF EXISTS os_holiday_override;
DROP TABLE IF EXISTS os_work_hours;

-- Service catalog / bridge tables
DROP TABLE IF EXISTS os_service;
DROP TABLE IF EXISTS other_service_bridge;
DROP TABLE IF EXISTS os_available_service;

-- Root provider table
DROP TABLE IF EXISTS other_service;

SET FOREIGN_KEY_CHECKS = 1;

-- =====================================================================
-- OPTIONAL: orphaned foreign-key columns left on shared tables
-- =====================================================================
-- OtherService mapped several @OneToMany relationships with @JoinColumn,
-- which placed FK columns on the media_file table:
--     media_file.company_trade_license   -> other_service.id
--     media_file.company_vat_certificate -> other_service.id
--     media_file.company_images          -> other_service.id
-- (media_file.company_logo and location.company_location FKs live on
--  other_service itself and are removed with that table.)
--
-- These columns are now harmless (they just hold NULLs / stale ids), but
-- if you want a clean schema, drop them. Constraint names are
-- auto-generated, so first find them:
--
--   SELECT CONSTRAINT_NAME, COLUMN_NAME
--   FROM information_schema.KEY_COLUMN_USAGE
--   WHERE TABLE_SCHEMA = DATABASE()
--     AND TABLE_NAME = 'media_file'
--     AND COLUMN_NAME IN ('company_trade_license','company_vat_certificate','company_images');
--
-- Then, for each constraint returned:
--   ALTER TABLE media_file DROP FOREIGN KEY <constraint_name>;
--
-- Finally drop the columns:
--   ALTER TABLE media_file DROP COLUMN company_trade_license;
--   ALTER TABLE media_file DROP COLUMN company_vat_certificate;
--   ALTER TABLE media_file DROP COLUMN company_images;
-- =====================================================================
